-- Athena saved query (Product_B2C_Intl)
-- ID: 0cf6e66c-8030-4156-95b2-2fde25d52dc2
-- Name: Contextual Filter - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH abexp AS ( SELECT event_group, event_name, variantname, mri_session_id FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2025-12-08 00:00:00' AND __time < TIMESTAMP '2025-12-23 00:00:00' AND header_bu = 'BUS' AND selected_country = 'India' AND event_src = 'Android' AND event_group IN ('ab_exp_redDealfilters') AND event_name IN ('redDeal filter shown') GROUP BY event_group, event_name, event_value, mri_session_id, variantname ), srpload AS ( SELECT event_group, event_name, mri_session_id FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2025-12-08 00:00:00' AND __time < TIMESTAMP '2025-12-23 00:00:00' AND header_bu = 'BUS' AND selected_country = 'India' AND event_src = 'Android' AND event_group IN ('srp_click_event') AND event_name IN ('Contextual Filters') ), slload AS ( SELECT event_group, event_name, mri_session_id FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2025-12-08 00:00:00' AND __time < TIMESTAMP '2025-12-23 00:00:00' AND header_bu = 'BUS' AND selected_country = 'India' AND event_src = 'Android' AND event_group IN ('purchase','PURCHASE') ), confirms AS ( SELECT mri_session_id, tin FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2025-12-08 00:00:00' AND __time < TIMESTAMP '2025-12-23 00:00:00' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') ) SELECT a.event_group, a.event_name, a.variantname, s.event_group, s.event_name , COUNT(DISTINCT a.mri_session_id) AS abload_sessions, COUNT(DISTINCT s.mri_session_id) AS srp_sessions, COUNT(DISTINCT sl.mri_session_id) AS sl_sessions, COUNT(DISTINCT c.mri_session_id) AS confirm_sessions, COUNT(DISTINCT c.tin) AS txn_count FROM abexp a inner join srpload s ON a.mri_session_id = s.mri_session_id left join slload sl ON s.mri_session_id = sl.mri_session_id left join confirms c ON s.mri_session_id = c.mri_session_id GROUP BY a.event_group, a.event_name, a.variantname, s.event_group, s.event_name
